<script setup lang="ts">
import {onMounted,ref,computed} from 'vue';
import {governance} from '../governance';
const projects=ref<any[]>([]),sources=ref<any[]>([]),selected=ref<any>(null),source=ref<any>(null),query=ref(''),error=ref(''),available=ref(false);
const types:Record<string,string>={tender:'招标文件',drawings:'施工图',boq:'工程量清单',contract:'合同',settlement:'结算资料',acceptance:'验收资料',material_price_basis:'材料价格依据',quota_basis:'定额依据',reference:'参考成果'};
const stateLabels:Record<string,string>={MISSING:'缺失',FILE_PRESENT_PARSE_FAILED:'文件在，解析失败',ARCHIVE_PARSED_UNREVIEWED:'已解包，待复核',FILE_PRESENT_UNREVIEWED:'文件在，待复核',REFERENCE_ONLY:'仅参考',PARTIAL:'部分具备'};
function state(p:any,key:string){const s=p.document_status?.[key]?.status;return stateLabels[s]||s||'';}
function provenance(p:any){const s=p.source_completeness;return typeof s==='object'?`${s.hash_matched}/${s.files} 原件哈希一致；${s.with_direct_url} 份有直接URL`:(s||'待核验');}
const filtered=computed(()=>sources.value.filter(s=>!query.value||JSON.stringify(s).toLowerCase().includes(query.value.toLowerCase())));
async function load(){try{error.value='';const [p,s]=await Promise.all([governance('/projects'),governance('/sources?limit=250')]);projects.value=p.items;sources.value=s.items;available.value=p.available&&s.available;}catch(e){error.value=String(e);}}
onMounted(load);
</script>
<template>
  <section>
    <div class="panel"><h2>项目资料完整性与来源核验</h2><p class="hint">A_INPUT 为原始输入，B_REFERENCE 为已发布参考成果。参考清单不能证明系统独立算量。生产验收：False；E 级精度：BLOCKED。</p><button class="btn" @click="load" data-testid="readiness-refresh">刷新资料矩阵</button><p v-if="!available" class="hint">尚未载入资料盘点快照，请先完成本机数据初始化。</p><p v-if="error" role="alert">{{error}}</p>
    <div class="table-wrap matrix-scroll"><table data-testid="project-matrix"><thead><tr><th>项目</th><th>地点 / 类型 / 阶段</th><th v-for="(label,key) in types" :key="key">{{label}}</th><th>来源 / 授权</th><th>L1 算量验证</th></tr></thead><tbody><tr v-for="p in projects" :key="p.project_id"><td><button class="link" @click="selected=p" data-testid="project-detail">{{p.name}}</button><small>{{p.project_id}}</small></td><td>{{p.location}}<br>{{p.engineering_type}}<br>{{p.stage}}</td><td v-for="(label,key) in types" :key="key">{{p.documents?.[key]?.length??0}} 份<small>{{state(p,String(key))}}</small></td><td>{{provenance(p)}}<br>复用授权待核验</td><td>{{p.l1_quantity_status}}</td></tr></tbody></table></div><p data-testid="readiness-count">有权访问 {{projects.length}} 套项目</p></div>
    <div v-if="selected" class="panel" data-testid="readiness-detail"><h3>{{selected.name}}</h3><p><b>缺少资料：</b>{{Array.isArray(selected.missing)?selected.missing.join('；'):selected.missing}}</p><p><b>可用于测试：</b>{{Array.isArray(selected.allowed_tests)?selected.allowed_tests.join('；'):selected.allowed_tests}}</p><div class="table-wrap"><table><thead><tr><th>资料 / 数据角色</th><th>格式</th><th>来源编号</th><th>原件 SHA256</th></tr></thead><tbody><tr v-for="f in selected.files" :key="f.path"><td>{{f.path}}<br><b>{{f.data_role}}</b></td><td>{{f.format}}</td><td>{{f.source_id}}</td><td class="hash">{{f.sha256}}</td></tr></tbody></table></div></div>
    <div class="panel"><h3>来源状态</h3><label>按编号 / 资料 / 状态搜索<input v-model="query" data-testid="source-search" placeholder="例如 SRC-0155" /></label><p>有权访问 {{sources.length}} 项来源。来源核查、授权和正式业务适用性分别记录。</p><div class="table-wrap source-scroll"><table data-testid="source-status"><thead><tr><th>编号</th><th>资料</th><th>核查状态</th><th>授权状态</th><th>来源 URL</th><th>哈希</th></tr></thead><tbody><tr v-for="s in filtered" :key="s.source_id"><td><button class="link" @click="source=s">{{s.source_id}}</button></td><td>{{s.title||s.local_path}}</td><td>{{s.verification_status}}</td><td>{{s.authorization_status}}</td><td><a v-if="s.source_url&&/^https?:\/\//.test(s.source_url)" :href="s.source_url" target="_blank" rel="noopener noreferrer">查看来源</a><span v-else>无直接 URL，见来源链</span></td><td>{{s.hash_match?'一致':'待核验'}}</td></tr></tbody></table></div><pre v-if="source" data-testid="source-audit-detail">{{JSON.stringify(source,null,2)}}</pre></div>
  </section>
</template>
<style scoped>small{display:block;color:#64748b}.link{border:0;background:transparent;color:#1d4ed8;cursor:pointer;padding:4px;text-align:left}.hash{overflow-wrap:anywhere;max-width:330px;font-size:12px}.source-scroll{max-height:520px}.matrix-scroll{max-height:640px}.matrix-scroll table{min-width:1780px;table-layout:fixed}.matrix-scroll th:first-child{width:200px}.matrix-scroll th:nth-child(2){width:180px}.matrix-scroll th:nth-last-child(2){width:180px}.matrix-scroll th{width:95px}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:450px;overflow:auto}label{display:block;margin:12px 0}label input{margin-left:10px;min-width:260px}table{font-size:13px}td{min-width:85px;white-space:normal}</style>
